    # Ensure page is stable before interacting
    await page.wait_for_load_state("networkidle")

    # 1) Set Tax Class on the Prices tab (required field). Prefer exact label with asterisk.
    try:
        await page.get_by_role("combobox", name="Tax Class *").select_option(label="Taxable Goods")
    except Exception:
        try:
            # Fallback: try without asterisk
            await page.get_by_role("combobox", name="Tax Class").select_option(label="Taxable Goods")
        except Exception:
            # If cannot set Tax Class, continue—Save will fail but we shouldn't raise here.
            pass

    # 2) Open the Inventory tab to set Qty and Stock Availability
    try:
        await page.get_by_role("link", name="Inventory").click()
