            await page.get_by_label("Name").fill("Energy-Bulk Man Yoga Pant")
        except Exception:
            pass

    # 3b) Ensure SKU is set (use a sensible SKU)
    try:
        await page.get_by_label("SKU *").fill("EBM-YOGA-PANT-38-YELLOW")
    except Exception:
        try:
            await page.get_by_label("SKU").fill("EBM-YOGA-PANT-38-YELLOW")
        except Exception:
            pass

    # 3c) Set Size -> 38 (prefer combobox, fallback to input)
    try:
        await page.get_by_role("combobox", name="Size").select_option(label="38")
    except Exception:
        try:
            await page.get_by_label("Size").fill("38")
        except Exception:
            pass

    # 3d) Set Color -> Yellow (prefer combobox, fallback to input)
    try:
        await page.get_by_role("combobox", name="Color").select_option(label="Yellow")
    except Exception:
        try:
            await page.get_by_label("Color").fill("Yellow")
        except Exception:
            pass

    # 4) Final action: click Save (this navigates away). Must be last.
    try:
        await page.get_by_role("button", name="Save").click()
    except Exception:
        try:
            # Fallback: any button that contains 'Save' in its name
            await page.get_by_role("button", name=lambda n: n and "Save" in n).click()
        except Exception:
            pass

    # Wait for save/navigation to complete
    await page.wait_for_load_state("networkidle")

