async def act(page):
    """From the current Prices tab, complete missing required fields and the
    remaining product details for "Energy-Bulk Man Yoga Pant":
      - Ensure Tax Class is set (Taxable Goods)
      - Open Inventory and set Qty=50 and Stock Availability=In Stock
      - Open General and ensure Name, SKU, Size=38, Color=Yellow
      - Click Save (final action)

    Save is the last action because it navigates away.
    """

    # Ensure page is stable before interacting
    await page.wait_for_load_state("networkidle")

    # 1) Set Tax Class on the Prices tab (required field). Prefer exact label with asterisk.
    try:
        await page.get_by_role("combobox", name="Tax Class *").select_option(label="Taxable Goods")
    except Exception:
        try:
            # Fallback: try without asterisk
            await page.get_by_role("combobox", name="Tax Class").select_option(label="Taxable Goods")
        except Exception:
            # If cannot set Tax Class, continue—Save will fail but we shouldn't raise here.
            pass

    # 2) Open the Inventory tab to set Qty and Stock Availability
    try:
        await page.get_by_role("link", name="Inventory").click()
        await page.wait_for_load_state("networkidle")
    except Exception:
        # If clicking the Inventory link fails, fields might already be visible; continue.
        pass

    # 2a) Set Quantity to 50. Try common label variants and a textbox fallback.
    qty_set = False
    for qty_label in ("Qty", "Quantity"):
        try:
            await page.get_by_label(qty_label).fill("50")
            qty_set = True
            break
        except Exception:
            continue
    if not qty_set:
        try:
            await page.get_by_role("textbox", name="Qty").fill("50")
        except Exception:
            pass

    # 2b) Set Stock Availability -> In Stock (combobox preferred)
    try:
        await page.get_by_role("combobox", name="Stock Availability").select_option(label="In Stock")
    except Exception:
        try:
            await page.get_by_label("In Stock").check()
        except Exception:
            pass

    # 3) Open the General tab to set Name, SKU, Size, Color if needed
    try:
        await page.get_by_role("link", name="General").click()
        await page.wait_for_load_state("networkidle")
    except Exception:
        # If clicking fails, the fields might still be accessible; continue.
        pass

    # 3a) Ensure Name is set to the requested value
    try:
        await page.get_by_label("Name *").fill("Energy-Bulk Man Yoga Pant")
    except Exception:
        try:
            await page.get_by_label("Name").fill("Energy-Bulk Man Yoga Pant")
        except Exception:
            pass

    # 3b) Ensure SKU is set (use a sensible SKU)
    try:
        await page.get_by_label("SKU *").fill("EBM-YOGA-PANT-38-YELLOW")
    except Exception:
        try:
            await page.get_by_label("SKU").fill("EBM-YOGA-PANT-38-YELLOW")
        except Exception:
            pass

    # 3c) Set Size -> 38 (prefer combobox, fallback to input)
    try:
        await page.get_by_role("combobox", name="Size").select_option(label="38")
    except Exception:
        try:
            await page.get_by_label("Size").fill("38")
        except Exception:
            pass

    # 3d) Set Color -> Yellow (prefer combobox, fallback to input)
    try:
        await page.get_by_role("combobox", name="Color").select_option(label="Yellow")
    except Exception:
        try:
            await page.get_by_label("Color").fill("Yellow")
        except Exception:
            pass

    # 4) Final action: click Save (this navigates away). Must be last.
    try:
        await page.get_by_role("button", name="Save").click()
    except Exception:
        try:
            # Fallback: any button that contains 'Save' in its name
            await page.get_by_role("button", name=lambda n: n and "Save" in n).click()
        except Exception:
            pass

    # Wait for save/navigation to complete
    await page.wait_for_load_state("networkidle")
